#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QAbstractButton>
#include <QApplication>
#include <QFile>
#include <QDir>
#include <QFileDialog>
#include <QMenu>
#include <QMenuBar>
#include <QMessageBox>
#include <QPointer>
#include <QTableView>
#include <QTemporaryDir>
#include <QTest>
#include <QTimer>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
QString csv(QTemporaryDir& files,const QString& name,const QByteArray& text){QFile file(files.filePath(name));require(file.open(QIODevice::WriteOnly)&&file.write(text)==text.size(),"prepare a synthetic workbook");return file.fileName();}
QList<QPointer<MainWindow>> otherWindows(MainWindow& original){QList<QPointer<MainWindow>> result;for(auto* widget:QApplication::topLevelWidgets())if(auto* window=dynamic_cast<MainWindow*>(widget);window&&window!=&original)result.push_back(window);return result;}
struct Cleanup {MainWindow& original;~Cleanup(){for(auto window:otherWindows(original))if(window)delete window;}};
struct OpenDriver {
 QTimer timer;QString path,destination;QMessageBox::StandardButton unsavedChoice;int files=0,locations=0,unsaved=0,unexpected=0,saveErrors=0,openErrors=0;bool cancelFileDialog=false;
 OpenDriver(QString file,QString choice,QMessageBox::StandardButton changes=QMessageBox::Cancel):path(std::move(file)),destination(std::move(choice)),unsavedChoice(changes){timer.setInterval(0);QObject::connect(&timer,&QTimer::timeout,[this]{auto* active=QApplication::activeModalWidget();if(!active)return;if(auto* dialog=qobject_cast<QFileDialog*>(active)){if(files++)return;if(cancelFileDialog){dialog->reject();return;}dialog->selectFile(path);QMetaObject::invokeMethod(dialog,"accept",Qt::DirectConnection);return;}if(auto* dialog=qobject_cast<QMessageBox*>(active)){if(dialog->objectName()=="workbook.openLocation"){++locations;if(auto* button=dialog->findChild<QAbstractButton*>(destination))QTest::mouseClick(button,Qt::LeftButton);else{++unexpected;dialog->reject();}}else if(dialog->objectName()=="workbook.openUnsaved"){++unsaved;QTest::mouseClick(dialog->button(unsavedChoice),Qt::LeftButton);}else if(dialog->windowTitle()=="Cannot save workbook"){++saveErrors;dialog->accept();}else if(dialog->windowTitle()=="Cannot open workbook"){++openErrors;dialog->accept();}else{++unexpected;dialog->reject();}}});timer.start();}
 ~OpenDriver(){timer.stop();}
};
void openFromFile(MainWindow& window){QAction* file=nullptr;for(auto* action:window.menuBar()->actions())if(action->text()=="File")file=action;require(file&&file->menu(),"File menu is available");QTest::mouseClick(window.menuBar(),Qt::LeftButton,Qt::NoModifier,window.menuBar()->actionGeometry(file).center());QApplication::processEvents();auto* menu=file->menu();QAction* open=nullptr;for(auto* action:menu->actions())if(action->text()=="Open…")open=action;require(menu->isVisible()&&open,"the actual native File menu exposes Open");QTest::mouseClick(menu,Qt::LeftButton,Qt::NoModifier,menu->actionGeometry(open).center());QApplication::processEvents();}
WorksheetModel* model(MainWindow& window){return dynamic_cast<WorksheetModel*>(window.findChild<QTableView*>("worksheet.grid")->model());}
void chooseLocation(){for(const bool newWindow:{false,true}){QTemporaryDir files;const auto current=csv(files,"Current.csv","11\n"),target=csv(files,"Target.csv","22\n");MainWindow window;Cleanup cleanup{window};window.show();window.activateWindow();require(window.openWorkbook(current),"open a nonblank current workbook");const auto before=window.currentSession().snapshot();OpenDriver driver(target,newWindow?"open.newWindow":"open.currentWindow");openFromFile(window);require(driver.files==1&&driver.locations==1&&!driver.unexpected,"File Open offers a current/new-window choice after choosing the file");const auto others=otherWindows(window);if(newWindow){require(others.size()==1&&others.front()->isVisible()&&others.front()->windowFilePath()==target&&model(*others.front())->raw(0,0)=="22","New window opens the chosen file in one independent visible window");require(window.currentSession().snapshot()==before&&window.windowFilePath()==current,"New window preserves the current workbook and its identity");}else require(others.isEmpty()&&window.windowFilePath()==target&&model(window)->raw(0,0)=="22","This window opens the chosen workbook in the existing window");}}
void blankAlwaysReuses(){QTemporaryDir files;const auto target=csv(files,"Target.csv","22\n");MainWindow window;Cleanup cleanup{window};window.show();window.activateWindow();OpenDriver driver(target,"open.newWindow");openFromFile(window);require(driver.files==1&&!driver.locations&&!driver.unexpected&&otherWindows(window).isEmpty()&&window.windowFilePath()==target&&model(window)->raw(0,0)=="22","an untouched blank workbook opens directly in this window without a destination prompt");}
void cancelKeepsCurrent(){QTemporaryDir files;const auto current=csv(files,"Current.csv","11\n"),target=csv(files,"Target.csv","22\n");MainWindow window;Cleanup cleanup{window};window.show();window.activateWindow();require(window.openWorkbook(current),"prepare current workbook for cancellation");const auto before=window.currentSession().snapshot();OpenDriver driver(target,"open.cancel");openFromFile(window);require(driver.locations==1&&!driver.unexpected&&otherWindows(window).isEmpty()&&window.windowFilePath()==current&&window.currentSession().snapshot()==before,"Cancel keeps the current workbook without creating windows or showing errors");}
void dirtyCurrentChoice(){for(const auto choice:{QMessageBox::Save,QMessageBox::Discard,QMessageBox::Cancel}){QTemporaryDir files;const auto current=csv(files,"Current.csv","11\n"),target=csv(files,"Target.csv","22\n");MainWindow window;Cleanup cleanup{window};window.show();window.activateWindow();require(window.openWorkbook(current)&&model(window)->setData(model(window)->index(0,0),"99",Qt::EditRole),"prepare unsaved current data");const auto before=window.currentSession().snapshot();OpenDriver driver(target,"open.currentWindow",choice);const bool result=window.executeCommand("open",{{"path",target.toStdString()}});require(driver.locations==1&&driver.unsaved==1&&!driver.unexpected,"This window asks Save/Discard/Cancel before replacing unsaved changes");require(otherWindows(window).isEmpty(),"This window honors its destination instead of silently opening another window");QFile original(current);require(original.open(QIODevice::ReadOnly),"read the synthetic original after the choice");const auto bytes=original.readAll();if(choice==QMessageBox::Save)std::cout<<"saved scalar CSV bytes="<<bytes.toHex().toStdString()<<'\n';require(choice==QMessageBox::Save?bytes.trimmed()=="99":bytes=="11\n","only choosing Save writes the previous workbook value; Discard and Cancel preserve its exact bytes");if(choice==QMessageBox::Cancel)require(!result&&window.currentSession().snapshot()==before&&window.windowFilePath()==current&&window.isWindowModified()&&window.currentSession().canUndo(),"Cancel preserves unsaved data, original identity and Undo");else require(result&&window.windowFilePath()==target&&model(window)->raw(0,0)=="22"&&!window.isWindowModified(),"Save or Discard completes opening in this same window");}}
void saveBoundaries(){
 for(const bool exportOnly:{false,true}){QTemporaryDir files;const auto target=csv(files,"Target.csv","22\n");MainWindow window;Cleanup cleanup{window};window.show();window.activateWindow();if(exportOnly)require(window.openWorkbook(csv(files,"Current.csv","11\n")),"open a CSV source for export-only save");require(model(window)->setData(model(window)->index(0,0),exportOnly?"=1+2":"99",Qt::EditRole),"prepare unsaved formula or untitled data");const auto before=window.currentSession().snapshot();const auto originalPath=window.windowFilePath();OpenDriver driver(target,"open.currentWindow",QMessageBox::Save);driver.cancelFileDialog=!exportOnly;require(!window.executeCommand("open",{{"path",target.toStdString()}})&&driver.locations==1&&driver.unsaved==1&&!driver.unexpected,"cancelled Save As and export-only CSV saves both stop workbook replacement");require(window.currentSession().snapshot()==before&&window.windowFilePath()==originalPath&&window.isWindowModified()&&window.currentSession().canUndo()&&otherWindows(window).isEmpty(),"an incomplete save preserves all unsaved data, document identity and Undo");require(exportOnly||driver.files==1,"an untitled workbook asks where to save before opening here");}
}
void failedSaveRecent(){
 QTemporaryDir files;const auto target=csv(files,"Target.csv","22\n"),folder=files.filePath("current"),current=folder+"/Current.xlsx";require(QDir().mkpath(folder),"create an isolated writable workbook directory");MainWindow window;Cleanup cleanup{window};window.show();window.activateWindow();require(window.openWorkbook(target)&&window.saveWorkbook(current)&&model(window)->setData(model(window)->index(0,0),"99",Qt::EditRole),"prepare a saved workbook with a pending change");require(QFile::remove(current)&&QDir().rmdir(folder),"make only the synthetic original save destination unavailable");const auto before=window.currentSession().snapshot();auto* recent=window.findChild<QMenu*>("file.openRecent");require(recent,"Recent menu exists");QMetaObject::invokeMethod(recent,"aboutToShow",Qt::DirectConnection);QAction* action=nullptr;for(auto* item:recent->actions())if(item->data().toString()==target)action=item;require(action&&action->isEnabled(),"the test target remains in Open Recent");OpenDriver driver(target,"open.currentWindow",QMessageBox::Save);action->trigger();require(driver.locations==1&&driver.unsaved==1&&driver.saveErrors==1&&driver.openErrors==0&&!driver.unexpected,"a failed save shows its actual save error once without an extra Cannot open warning");require(window.currentSession().snapshot()==before&&window.windowFilePath()==current&&window.isWindowModified()&&window.currentSession().canUndo()&&otherWindows(window).isEmpty(),"a failed save keeps the original unsaved workbook and does not open the recent file");
}
}
int main(int argc,char** argv){QApplication app(argc,argv);try{const std::string mode=argc>1?argv[1]:"all";for(const auto& test:{std::pair{"choice",chooseLocation},std::pair{"blank",blankAlwaysReuses},std::pair{"cancel",cancelKeepsCurrent},std::pair{"dirty",dirtyCurrentChoice},std::pair{"save_boundaries",saveBoundaries},std::pair{"save_failure",failedSaveRecent}})if(mode=="all"||mode==test.first){QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());test.second();}std::cout<<"workbook open location tests passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
